e -->\n    <circle cx=\"4\"\n            cy=\"-2\"\n            r=\"2\"\n            fill=\"#0A0812\"/>\n\n    <!-- frown -->\n    <path d=\"M-4 8 Q0 5 4 8\"\n          fill=\"none\"\n          stroke=\"#0A0812\"\n          stroke-width=\"2\"/>\n\n    <!-- robe -->\n    <path d=\"\n      M-22 18\n      L22 18\n      L28 90\n      L-28 90 Z\"\n      fill=\"#4f6980\"\n      stroke=\"#0A0812\"\n      stroke-width=\"3\"/>\n\n    <!-- slumped shoulders -->\n    <line x1=\"-22\"\n          y1=\"35\"\n          x2=\"-45\"\n          y2=\"45\"\n          stroke=\"#0A0812\"\n          stroke-width=\"4\"\n          stroke-linecap=\"round\"/>\n\n    <line x1=\"22\"\n          y1=\"35\"\n          x2=\"40\"\n          y2=\"50\"\n          stroke=\"#0A0812\"\n          stroke-width=\"4\"\n          stroke-linecap=\"round\"/>\n\n  </g>\n\n  <!-- Visual focus line (Jonah to plant) -->\n  <path d=\"\n      M180 265\n      Q210 235 245 230\n      Q270 225 285 245\"\n      fill=\"none\"\n      stroke=\"#ffffff\"\n      stroke-width=\"2\"\n      opacity=\"0.15\"/>\n\n  <!-- Tiny distant city silhouette -->\n  <g opacity=\"0.25\"\n     transform=\"translate(470 220) scale(0.5)\">\n\n    <rect x=\"0\" y=\"40\"\n          width=\"140\"\n          height=\"50\"\n          fill=\"#d39a61\"\n          stroke=\"#0A0812\"\n          stroke-width=\"3\"/>\n\n    <rect x=\"20\" y=\"-10\"\n          width=\"30\"\n          height=\"100\"\n          fill=\"#c38449\"/>\n\n    <rect x=\"70\" y=\"-30\"\n          width=\"40\"\n          height=\"120\"\n          fill=\"#c38449\"/>\n\n  </g>\n\n  <!-- First evening stars -->\n  <g fill=\"#ffffff\" opacity=\"0.75\">\n\n    <circle cx=\"90\" cy=\"35\" r=\"1.4\"/>\n    <circle cx=\"130\" cy=\"55\" r=\"1.2\"/>\n    <circle cx=\"220\" cy=\"45\" r=\"1.5\"/>\n    <circle cx=\"540\" cy=\"40\" r=\"1.4\"/>\n\n  </g>\n\n</svg>", "Jonah/assets/svg/Act4-08-THE END.svg": "<svg viewBox=\"0 0 600 400\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <linearGradi